pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs, address prankedSender) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(prankedSender != address(this));
        vm.assume(prankedSender != address(0));
        TokenRecorder recorder = new TokenRecorder();
        vm.prank(prankedSender);
        c.transfer(address(recorder), tos, vs);
        assertTrue(recorder.lastFrom() == prankedSender);
    }
}

contract TokenRecorder {
    address public lastFrom;
    function transferFrom(address from, address, uint256) external returns (bool) {
        lastFrom = from;
        return true;
    }
}
